-- Translators: Claude (AI-assisted, not yet reviewed by a native speaker), Codex (AI-assisted, not yet reviewed by a native speaker)
-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "esMX" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.shaman.elemental.Name"] = "Elemental"
L["rm.era.shaman.elemental.Description"] = "Elemental desde el nivel 10 (la mayoría de los puntos en Elemental); basada en Icy Veins y Wowhead. Choque de tierra interrumpe y remata a un objetivo a punto de morir. En movimiento: Choque de llamas y, si no, Choque de Escarcha. En solitario con el objetivo cuerpo a cuerpo: Choque de tierra por encima del 30 % de salud, y después cuerpo a cuerpo. Contra tres o más enemigos: los tótems Nova de Fuego y de magma cuando estás cuerpo a cuerpo, y Cadena de relámpagos. Cadena de relámpagos con Maestría elemental o Lanzamiento libre y, si no, Descarga de relámpagos. Recordatorios: Escudo de relámpagos, Muerdepiedras fuera de bandas, Tótem abrasador o de magma, Fuente de maná o Corriente de sanación, Maestría elemental con Cadena de relámpagos lista, Presteza de la Naturaleza y Ola de sanación por debajo del 30 %, y sanarte tras un combate. Las disipaciones, las purgas y usar rangos inferiores quedan a tu cargo."
L["rm.era.shaman.elemental.simulator.Name"] = "Elemental, Cadena de relámpagos cada vez que esté disponible (simulador)"
L["rm.era.shaman.elemental.simulator.Description"] = "La lista Elemental de simulador, una alternativa a la rotación integrada de Elemental recomendada, desactivada de forma predeterminada: actívala y desactiva aquella, o aumenta su prioridad. Cadena de relámpagos cada vez que esté disponible, incluso contra un solo objetivo, Choque de tierra mientras Maestría elemental esté activa y, si no, Descarga de relámpagos. Más rápida, pero consume mucho más maná que la rotación integrada recomendada; la misma interrupción, tótems y recordatorios."
L["rm.era.shaman.enhancement.Name"] = "Mejora"
L["rm.era.shaman.enhancement.Description"] = "Niveles 1–60, también en reinos Extremos y en modo autosuficiente, y cualquier chamán sin mayoría de talentos en un árbol; basada en Icy Veins, Wowhead y simulador. Descarga de relámpagos inicia el combate a distancia; Choque de tierra interrumpe. En bandas, solo Golpe de tormenta y Choque de Escarcha (por los huecos de perjuicios). Con tres o más enemigos luchando contra ti, los tótems Nova de Fuego y de magma. Después, Golpe de tormenta, Choque de tierra durante el perjuicio de Golpe de tormenta o para rematar, Choque de llamas cuando vaya a durar completo, Choque de tierra mientras tengas la mitad de tu maná, y Descarga de relámpagos mientras el objetivo esté fuera de alcance. Recordatorios: Muerdepiedras en solitario y Arma Viento Furioso en mazmorras, Escudo de relámpagos, Fuerza de la tierra, Tótem abrasador, Viento Furioso o Gracia del aire, Fuente de maná o Corriente de sanación, y sanarte tras un combate y en emergencias. Garra de piedra, Nexo Terrestre, la alternancia de tótems y las habilidades raciales aparecen en la lista pero desactivados; las disipaciones, las purgas y los tótems de limpieza quedan a tu cargo."
L["rm.era.shaman.enhancement.warcrafttavern.Name"] = "Mejora, primero Choque de llamas (Warcraft Tavern)"
L["rm.era.shaman.enhancement.warcrafttavern.Description"] = "La Mejora de Warcraft Tavern, una alternativa a la rotación integrada de Mejora recomendada, desactivada de forma predeterminada: actívala y desactiva aquella, o aumenta su prioridad. Arma Viento Furioso en cuanto la aprendas, Golpe de tormenta, Choque de llamas antes de cualquier choque directo, y después Choque de tierra mientras tu amenaza sea baja, o Choque de Escarcha en grupo una vez que sea alta; magma y Cadena de relámpagos contra grupos de enemigos. Los mismos tótems y recordatorios que la rotación integrada recomendada."
L["rm.era.shaman.restoration.Name"] = "Restauración"
L["rm.era.shaman.restoration.Description"] = "Restauración desde el nivel 10 (la mayoría de los puntos en Restauración); basada en Icy Veins y Wowhead. Sobre tu objetivo amistoso: Ola de sanación bajo Presteza de la Naturaleza, Presteza de la Naturaleza por debajo del 30 %, Ola de sanación inferior por debajo del 40 %, Curar envenenamiento o Curar enfermedad, Sanación en cadena cuando tres miembros del grupo cerca de ti están por debajo del 85 % y, si no, Ola de sanación por debajo del 90 %. Contra un enemigo, combate: interrupción con Choque de tierra, Cadena de relámpagos contra grupos de enemigos, Choque de llamas, Descarga de relámpagos a distancia y cuerpo a cuerpo. Recordatorios: Escudo de relámpagos y Muerdepiedras en solitario, Marea de maná en grupo, Fuente de maná, Fuerza de la tierra, Tótem abrasador. Elegir a quién sanar, usar rangos inferiores y los tótems de tremor o de limpieza quedan a tu cargo; mantener Camino de sanación sobre el tanque aparece en la lista pero desactivado."
L["rm.era.shaman.restoration.warcrafttavern.Name"] = "Restauración, primero Sanación en cadena (Warcraft Tavern)"
L["rm.era.shaman.restoration.warcrafttavern.Description"] = "La Restauración de Warcraft Tavern, una alternativa a la rotación integrada de Restauración recomendada, desactivada de forma predeterminada: actívala y desactiva aquella, o aumenta su prioridad. Sanación en cadena es la sanación para cualquiera por debajo del 90 %, con Ola de sanación inferior para alguien a punto de morir; Ola de sanación solo es para un sanador asignado al tanque con Camino de sanación (aparece en la lista pero desactivado). Las mismas curaciones, daño contra enemigos y recordatorios de tótems que la rotación integrada recomendada."
L["rm.forever.shaman.elemental.Name"] = "Elemental"
L["rm.forever.shaman.elemental.Description"] = "Elemental a distancia una vez que Elemental es tu árbol de talentos principal con 21 puntos (el nivel de Ráfaga de lava), según Icy Veins (antes, la rotación integrada de Mejora juega el híbrido cuerpo a cuerpo que recomiendan todas las guías). Inicia el combate con Descarga de relámpagos (Cadena de relámpagos contra un grupo de enemigos), en movimiento solo lanza instantáneos, usa Nova de Fuego y Cadena de relámpagos contra tres o más enemigos, mantiene Choque de llamas activo, Ráfaga de lava cada vez que esté disponible, Golpe de tormenta y Choque de tierra si conoces Golpe de tormenta, Nova de Fuego con Lanzamiento libre en grupo y después Descarga de relámpagos. Recordatorios: escudo, imbuición de arma, Tótem abrasador o Tótem de Magma, tótems de grupo, Maestría elemental e interrupción. En Forever la salud y el maná están ocultos para los addons, así que curarte y detenerte a recuperar maná queda a tu criterio. Quedan a tu cargo: kitear con Nexo Terrestre, Choque de Escarcha, Purgar y los demás tótems."
L["rm.forever.shaman.enhancement.Name"] = "Mejora (Icy Veins)"
L["rm.forever.shaman.enhancement.Description"] = "Mejora cuerpo a cuerpo del nivel 1 al 60, y la opción predeterminada para cualquier chamán antes de Ráfaga de lava o del Tótem Marea de maná. Inicia el combate con Descarga de relámpagos a distancia y después Golpe de tormenta cada vez que esté disponible, una Descarga de relámpagos instantánea con cinco acumulaciones de Arma vorágine, Nova de Fuego (con un tótem de fuego colocado) y Choque de llamas contra tres o más enemigos, Choque de tierra aprovechando el perjuicio de Golpe de tormenta, Choque de llamas en grupo y Choque de tierra cada vez que esté disponible; Descarga de relámpagos cubre el hueco mientras el objetivo está fuera de alcance. En Forever la salud y el maná están ocultos para los addons, así que curarte y detenerte a recuperar maná queda a tu criterio (la rotación integrada de Wowhead ahorra maná en su lugar). Recordatorios: imbuición de arma (Viento Furioso; si no, Lengua de Fuego; si no, Muerdepiedras), Escudo de agua o de relámpagos, la interrupción con Choque de tierra, Tótem abrasador o Tótem de Magma, tótems de grupo, Ira del clarividente y Tótem Garra de piedra. Quedan a tu cargo: los preajustes de tótems, Choque de Escarcha, Purgar y los demás tótems."
L["rm.forever.shaman.enhancement.wowhead.Name"] = "Mejora, eficiente en maná (Wowhead)"
L["rm.forever.shaman.enhancement.wowhead.Description"] = "La Mejora de ahorro de maná de Wowhead y Mobalytics: el ataque automático hace el trabajo, Golpe de tormenta solo mientras no esté activa la regeneración de maná de Golpe de tormenta mejorado, sin Choque de tierra en la rotación (los choques sirven para iniciar el combate e interrumpir) y, en grupo o contra grupos de enemigos, Tótem abrasador con Nova de Fuego cada vez que esté disponible. Los mismos recordatorios de imbuición, escudo e interrupción que la rotación integrada de Icy Veins. Elígela en lugar de esa rotación integrada si te quedas sin maná. Una alternativa a la rotación integrada de Mejora recomendada, desactivada de forma predeterminada: actívala y desactiva aquella, o aumenta su prioridad."
L["rm.forever.shaman.restoration.Name"] = "Restauración"
L["rm.forever.shaman.restoration.Description"] = "Sanación una vez que Restauración es tu árbol de talentos principal con 16 puntos (el nivel del Tótem Marea de maná), según Icy Veins. Con un objetivo amistoso: una Ola de sanación instantánea una vez que uses Presteza de la Naturaleza, Curar envenenamiento y Curar enfermedad, Mareas Vivas sobre un objetivo que no lo tenga, Sanación en cadena en grupo y Ola de sanación. Eliges a quién sanar seleccionándolo como objetivo; en Forever la salud y el maná están ocultos para los addons, así que decidir cuándo usar Presteza de la Naturaleza y Ola de sanación inferior queda a tu criterio. Con un objetivo hostil y nadie a quien sanar: Nova de Fuego y Cadena de relámpagos contra grupos de enemigos, Golpe de tormenta y Choque de tierra si conoces Golpe de tormenta, Choque de llamas sobre élites y jefes, Descarga de relámpagos y después cuerpo a cuerpo. Recordatorios: Escudo de agua, la interrupción con Choque de tierra, Marea de maná y los tótems de beneficio de grupo. Quedan a tu cargo: usar rangos inferiores, los demás tótems, Purgar y Lobo fantasmal."
L["rm.mop.shaman.elemental.Name"] = "Recomendada"
L["rm.mop.shaman.elemental.Description"] = "Recomendada para Elemental desde el nivel 10, elegida en la especialización Elemental. El orden de Wowhead: una Descarga de relámpagos para abrir (Ráfaga de lava con Furia desatada), Desatar elementos con Furia desatada, Choque de llamas cuando falta o está a punto de agotarse sobre un objetivo que vaya a sobrevivir, Ráfaga de lava sobre Choque de llamas (y con cada Oleada de lava), Explosión elemental, Choque de tierra con seis cargas de Escudo de relámpagos mientras a Choque de llamas le queden 6 segundos, Cadena de relámpagos contra dos enemigos, Descarga de relámpagos. Con cuatro o más enemigos luchando contra ti: magma cuerpo a cuerpo, Ráfagas de lava gratuitas, Haz de lava en Ascensión, Cadena de relámpagos. En movimiento solo muestra instantáneos. Recordatorios: Escudo de relámpagos, Lengua de Fuego, Tótem abrasador, Elemental de Fuego contra élites y jefes, Maestría elemental, Ascensión tras una Ráfaga de lava, Presteza ancestral, Látigo de tormenta y Ansia de sangre en grupo, Corte de viento, Tormenta de truenos para recuperar maná, e Ira del chamán y Cambio astral con poca salud. Terremoto y Elemental de Tierra aparecen en la lista pero desactivados. Quedan a tu cargo: Gracia del caminaespíritus, Choque de llamas sobre objetivos adicionales y dónde colocarte."
L["rm.mop.shaman.enhancement.Name"] = "Recomendada"
L["rm.mop.shaman.enhancement.Description"] = "Recomendada para Mejora desde el nivel 10, elegida en la especialización Mejora. El orden de Wowhead: Desatar elementos mientras te acercas corriendo, y después Desatar elementos con Furia desatada, Explosión elemental y Descarga de relámpagos con cinco acumulaciones de Arma vorágine (o intercaladas con tres cuando a tu siguiente golpe le falta más de un segundo), Explosión de tormenta en Ascensión, Golpe de tormenta (Golpe primigenio antes del 26), Latigazo de lava, Choque de llamas bajo Desatar llama, Desatar elementos, Choque de tierra. Con dos o más enemigos luchando contra ti: Cadena de relámpagos en lugar de Descarga de relámpagos, Latigazo de lava para extender Choque de llamas, Nova de Fuego desde cuatro y magma desde seis. Recordatorios: Escudo de relámpagos, Viento Furioso en la mano derecha y Lengua de Fuego en la izquierda, Tótem abrasador, Elemental de Fuego, Espíritu feral, Ascensión tras Golpe de tormenta, Maestría elemental, Presteza ancestral, Látigo de tormenta y Ansia de sangre en grupo, Corte de viento, e Ira del chamán y Cambio astral con poca salud. Elemental de Tierra aparece en la lista pero desactivado."
L["rm.mop.shaman.enhancement.icyveins.Name"] = "Primero Latigazo de lava (Icy Veins)"
L["rm.mop.shaman.enhancement.icyveins.Description"] = "Desactivada por defecto; tiene la misma condición de cambio que la rotación integrada de Mejora recomendada, así que actívala y desactiva la otra para usarla. El orden de Icy Veins: Golpe de tormenta, y después Latigazo de lava antes de gastar Arma vorágine, Descarga de relámpagos con cinco acumulaciones o desde tres cuando impacta antes de tu siguiente golpe, Desatar elementos y después Choque de llamas, Choque de tierra. Contra cuatro o más enemigos extiende Choque de llamas con Latigazo de lava y usa Nova de Fuego; Cadena de relámpagos sustituye a Descarga de relámpagos contra grupos de enemigos. Ira del chamán se sugiere cada vez que esté disponible en combate; los demás recordatorios, como en la rotación integrada recomendada."
L["rm.mop.shaman.enhancement.simulator.Name"] = "Intercalar con cada acumulación (simulador)"
L["rm.mop.shaman.enhancement.simulator.Description"] = "Desactivada por defecto; tiene la misma condición de cambio que la rotación integrada de Mejora recomendada, así que actívala y desactiva la otra para usarla. La lista del simulador para quienes sincronizan lanzamientos entre golpes: Descarga de relámpagos, Explosión elemental o Cadena de relámpagos con cualquier número de acumulaciones de Arma vorágine siempre que el lanzamiento termine antes de tu siguiente golpe con la mano derecha, Desatar elementos también siempre que falte Choque de llamas, y Choque de tierra solo por debajo de dos acumulaciones. Los recordatorios, como en la rotación integrada recomendada."
L["rm.mop.shaman.restoration.Name"] = "Recomendada"
L["rm.mop.shaman.restoration.Description"] = "Recomendada para Restauración desde el nivel 10, elegida en la especialización Restauración. Sana a tu objetivo amistoso (Rotation Master no puede elegir a quién sanar): Ola de sanación superior bajo Presteza ancestral, Oleada de sanación por debajo del 35 %, Purificar espíritu contra magia o maldiciones, Desatar elementos y después Lluvia de sanación cuando tres aliados cercanos están heridos, Mareas Vivas, Sanación en cadena para daño al grupo, Ola de sanación superior por debajo del 60 % y Ola de sanación por debajo del 90 %. Con un objetivo atacable hace daño en su lugar (Choque de llamas, Ráfaga de lava, Explosión elemental, Descarga de relámpagos). Recordatorios: Escudo de agua, Vida terrestre, Escudo de tierra sobre tu foco, Corriente de sanación cuando alguien está herido, Marea de maná, Marea de sanación para daño fuerte al grupo, Maestría elemental o Guía ancestral, Presteza ancestral sobre un objetivo con poca salud, Gracia del caminaespíritus en movimiento, Ansia de sangre, Corte de viento. Ascensión y Tótem Enlace de espíritu aparecen en la lista pero desactivados: úsalos cuando tu banda te los asigne."
L["rm.mop.shaman.restoration.hekili.Name"] = "Escala de salud (Hekili)"
L["rm.mop.shaman.restoration.hekili.Description"] = "Desactivada por defecto; tiene la misma condición de cambio que la rotación integrada de Restauración recomendada, así que actívala y desactiva la otra para usarla. La lista de Hekili mantiene Escudo de tierra y Mareas Vivas sobre tu objetivo, y Corriente de sanación y Lluvia de sanación activas siempre que falten, y después sana según la salud media de tu grupo a menos de 40 metros: Sanación en cadena por debajo del 80 %, Ola de sanación sobre un objetivo por debajo del 70 %, Ola de sanación superior por debajo del 60 % y Oleada de sanación por debajo del 40 %, con Marea de sanación, Guía ancestral y Marea de maná en la misma escala. Un objetivo atacable recibe daño además de Choque de tierra."
L["rm.mop.shaman.unspecialized.Name"] = "Sin especialización"
L["rm.mop.shaman.unspecialized.Description"] = "Para los niveles 1 a 9 y cualquier chamán que aún no haya elegido especialización; cada rotación integrada de especialización toma el relevo en cuanto eliges una. Descarga de relámpagos para iniciar el combate a distancia, Oleada de sanación cuando tienes poca salud y estás solo, Golpe primigenio, Choque de tierra, y Descarga de relámpagos mientras estás fuera del alcance cuerpo a cuerpo. Mantiene Escudo de relámpagos."
L["rm.retail.shaman.elemental.Name"] = "Asistente de combate de Blizzard"
L["rm.retail.shaman.elemental.Description"] = "Recomendada para Elemental en Midnight. En combate, el juego ahora oculta a los addons Choque de llamas, tus beneficios, la Vorágine, los tiempos de reutilización y la salud, así que esta rotación muestra la propia sugerencia del Asistente de combate de Blizzard (la rotación de un solo botón), y se detiene mientras lanzas o no tienes un enemigo como objetivo. Recordatorios de lo que deja fuera: Ascensión, Elemental de Fuego o Elemental de tormenta y Presteza de la naturaleza en combate, Gracia del caminaespíritus en movimiento, Escudo de relámpagos y Abrasacielos entre combates (la sugerencia de Blizzard mantiene las imbuiciones de arma y de escudo), Corte de viento ante un lanzamiento interrumpible (solo se ilumina donde el juego permite leer el lanzamiento), Cambio astral siempre que esté disponible en combate (la salud está oculta en Retail, así que decidir cuándo usarlo queda a tu criterio)."
L["rm.retail.shaman.elemental.icyveins.Name"] = "De referencia (Icy Veins)"
L["rm.retail.shaman.elemental.icyveins.Description"] = "Solo de referencia, desactivada por defecto: el orden de Icy Veins y SimulationCraft lee Choque de llamas, Maestro de los elementos y Guardatormentas, que Midnight oculta en combate; la Vorágine está oculta en Retail, así que los gastadores se lanzan según su costo en lugar de con la Vorágine casi llena. Guardatormentas y Ráfaga de lava antes de iniciar el combate. Contra tres o más enemigos trabados en combate: Guardatormentas, Presteza ancestral, Choque de llamas, Cadena de relámpagos con Guardatormentas, Explosión elemental, Terremoto, Ráfaga de lava con Oleada de lava, Tempestad, Cadena de relámpagos. Si no, Guardatormentas, Presteza ancestral, Choque de llamas y Llamarada voltaica en su último 30 % fuera de Maestro de los elementos, Ráfaga de lava para activarlo, Tempestad y la Descarga de relámpagos de Guardatormentas dentro de él, Explosión elemental o Choque de tierra dentro de él, Llamarada voltaica, Tempestad, Choque de llamas o Choque de Escarcha en movimiento, Explosión elemental o Choque de tierra siempre que puedas permitírtelos, Descarga de relámpagos. Recordatorios: Ascensión una vez usado Guardatormentas, los elementales, Gracia del caminaespíritus y los compartidos."
L["rm.retail.shaman.enhancement.Name"] = "Asistente de combate de Blizzard"
L["rm.retail.shaman.enhancement.Description"] = "Recomendada para Mejora en Midnight. Muestra la sugerencia del Asistente de combate de Blizzard (gasta las acumulaciones de Arma vorágine, mantiene Choque de llamas y se encarga de Tótem volátil y Hendimiento), y se detiene mientras lanzas o no tienes un enemigo como objetivo. Recordatorios de lo que deja fuera: Ascensión, Vientos de perdición y Espíritu feral en combate, Escudo de relámpagos y Abrasacielos entre combates (la sugerencia de Blizzard mantiene Arma Viento Furioso), Corte de viento, Cambio astral."
L["rm.retail.shaman.enhancement.stormbringer.Name"] = "Portador de tormentas de referencia (SimulationCraft)"
L["rm.retail.shaman.enhancement.stormbringer.Description"] = "Solo de referencia, desactivada por defecto: la lista de Portador de tormentas de SimulationCraft (Icy Veins y Wowhead coinciden) lee Choque de llamas, Relámpago estruendoso, Llamas lacerantes y los temporizadores de los tiempos de reutilización, que Midnight oculta en combate. Contra tres o más enemigos trabados en combate: Relámpago estruendoso por su beneficio, Tempestad con 10 acumulaciones de Arma vorágine, Cadena de relámpagos con 9, Relámpago estruendoso, Latigazo de lava, Hendimiento. Después, Tormenta primordial con 9, Llamarada voltaica o Choque de llamas cuando falta Choque de llamas, Hendimiento, Relámpago estruendoso por su beneficio, Latigazo de lava para Llamas lacerantes, Golpe de viento, Tempestad o Descarga de relámpagos con 10 (8 si Llamarada voltaica o Relámpago estruendoso están a punto de estar listos), Golpe de tormenta con dos cargas, Latigazo de lava, Golpe de tormenta, Llamarada voltaica, Relámpago estruendoso, Descarga de relámpagos con 5, Choque de llamas. Recordatorios: Vientos de perdición, Ascensión fuera de Vientos de perdición, Espíritu feral y los compartidos."
L["rm.retail.shaman.enhancement.totemic.Name"] = "Totémico de referencia (SimulationCraft)"
L["rm.retail.shaman.enhancement.totemic.Description"] = "Solo de referencia, desactivada por defecto: la lista de Totémico de SimulationCraft lee Choque de llamas, Mano ardiente, Torbellino de fuego, Relámpago estruendoso y Vientos de perdición, que Midnight oculta en combate. Contra tres o más enemigos trabados en combate: Relámpago estruendoso, Cadena de relámpagos con 5 acumulaciones de Arma vorágine. Después, Llamarada voltaica o Choque de llamas cuando falta Choque de llamas, Tótem volátil, Hendimiento, Latigazo de lava con Mano ardiente o Torbellino de fuego, Relámpago estruendoso por su beneficio, Tormenta primordial con 10, Golpe de viento, Relámpago estruendoso y Golpe de tormenta durante Vientos de perdición, Descarga de relámpagos con 5, Relámpago estruendoso, Latigazo de lava, Golpe de tormenta, Llamarada voltaica, Choque de llamas. Los mismos recordatorios que la referencia de Portador de tormentas."
L["rm.retail.shaman.initial.Name"] = "Asistente de combate de Blizzard"
L["rm.retail.shaman.initial.Description"] = "Recomendada antes de elegir una especialización (mientras el juego informa de la especialización inicial del chamán). Resalta el próximo hechizo que sugiere el Asistente de combate de Blizzard, el único consejo de rotación que el juego aún permite leer a un addon en el combate de Midnight; espera mientras lanzas o canalizas. Junto a él, los recordatorios que comparten todas las rotaciones integradas de chamán, cada uno una vez que conoces su hechizo. Cuando elijas una especialización al nivel 10, tomarán el relevo las rotaciones integradas de esa especialización."
L["rm.retail.shaman.restoration.Name"] = "Icy Veins"
L["rm.retail.shaman.restoration.Description"] = "Restauración en Midnight, como referencia: el Asistente de combate de Blizzard no cubre a los sanadores, el juego oculta la salud de todos en combate y Rotation Master elige un hechizo, no un objetivo, así que esta rotación ordena tus herramientas de sanación según su disponibilidad sobre lo que tengas como objetivo, y deja a tu cargo decidir a quién sanar. Sobre un objetivo amistoso: Tótem Corriente de sanación, Desatar vida, Lluvia de sanación en grupo, Tótem volátil, Mareas Vivas, Sanación en cadena en grupo, Ola de sanación. Sobre un enemigo: Choque de llamas cuando falta, Ráfaga de lava, Descarga de relámpagos. Recordatorios: Escudo de agua, Escudo de tierra sobre un objetivo amistoso y Abrasacielos entre combates; Presteza de la naturaleza en combate; Tótem de Marea de sanación y Tótem Enlace de espíritu en combate en grupo; Corte de viento; Cambio astral."
L["rm.sod.shaman.elemental.Name"] = "Elemental (SoD)"
L["rm.sod.shaman.elemental.Description"] = "Elemental de Temporada de descubrimiento desde el nivel 10 (la mayoría de los puntos en Elemental); basada en la fase 6 de simulador, Wowhead e Icy Veins. Choque de tierra interrumpe. En movimiento: Choque de llamas, Choque de tierra con ocho cargas de Escudo de relámpagos, y Ráfaga de lava o Cadena de relámpagos con una activación de Oleada de poder. Contra tres o más enemigos: Choque de llamas, Cadena de relámpagos, Nova de Fuego, Ráfaga de lava, Choque de tierra con ocho cargas, magma. Después, Ráfaga de lava con Oleada de poder, Choque de llamas siempre activo, Ráfaga de lava mientras dure tu Choque de llamas, Choque de tierra con ocho cargas, Cadena de relámpagos contra dos enemigos, Descarga de relámpagos. Recordatorios: Lengua de Fuego para Quemar, Escudo de relámpagos, Escudo de tierra sobre ti, Espíritu del alfa, Espíritu feral, Ira del chamán, Maestría elemental, tótems. Los abalorios, Proyección totémica, las disipaciones y las purgas quedan a tu cargo."
L["rm.sod.shaman.enhancement.Name"] = "Mejora (SoD)"
L["rm.sod.shaman.enhancement.Description"] = "Temporada de descubrimiento, niveles 1–60 con las runas a medida que las grabas, con dos armas o con un arma de dos manos, y cualquier chamán de Temporada de descubrimiento al que no se ajuste ninguna otra rotación integrada; basada en la fase 6 de simulador, Icy Veins y Wowhead. Choque de llamas inicia el combate; Choque de tierra interrumpe. Contra tres o más enemigos: magma, Nova de Fuego desde un tótem de fuego, Cadena de relámpagos con cuatro acumulaciones de Arma vorágine, Choque de llamas. Después, Ráfaga de lava con cinco acumulaciones de Arma vorágine, Golpe de tormenta, Latigazo de lava, Descarga de relámpagos con cinco acumulaciones, Choque de llamas cuando vaya a durar, Choque de tierra, Explosión de arrabio y Descarga de relámpagos a distancia. Recordatorios: Arma Viento Furioso (antes, Muerdepiedras), Lengua de Fuego en un arma de la mano izquierda con Latigazo de lava (si no, Viento Furioso; nunca en un escudo; una línea de Icy Veins con Viento Furioso en ambas manos aparece en la lista pero desactivada), Escudo de agua o de relámpagos, Espíritu del alfa, Espíritu feral, Ira del chamán por debajo del 65 % de maná, tótems, Guía ancestral. Proyección totémica, las disipaciones y las purgas quedan a tu cargo."
L["rm.sod.shaman.restoration.Name"] = "Restauración (SoD)"
L["rm.sod.shaman.restoration.Description"] = "Restauración de Temporada de descubrimiento desde el nivel 10 (la mayoría de los puntos en Restauración); basada en Icy Veins y Wowhead. Sobre tu objetivo amistoso: Mareas Vivas y después Ola de sanación inferior por debajo del 40 %, Curar envenenamiento o Curar enfermedad, Lluvia de sanación cuando tres miembros del grupo cerca de ti están por debajo del 85 %, Sanación en cadena cuando lo están dos (de inmediato con una activación de Oleada de poder), Mareas Vivas por debajo del 95 % para Maremotos, y Ola de sanación por debajo del 90 %. Contra un enemigo, combate. Recordatorios: Escudo de agua (antes, Escudo de relámpagos), Escudo de tierra sobre tu objetivo amistoso o sobre ti, Ira del chamán, Marea de maná, Fuente de maná y Fuerza de la tierra. Elegir a quién sanar y los tótems de tremor o de limpieza quedan a tu cargo."
L["rm.sod.shaman.tank.Name"] = "Tanque (SoD, Tradición de tierra)"
L["rm.sod.shaman.tank.Description"] = "Tanque de Temporada de descubrimiento, elegida una vez que tienes grabado Tradición de tierra; basada en Icy Veins, Wowhead, simulador y Warcraft Tavern. Choque de llamas inicia el combate. Choque de tierra provoca a un objetivo cuerpo a cuerpo que no te está atacando, e interrumpe. Contra dos o más enemigos: Explosión de arrabio, Choque de llamas, Cadena de relámpagos con cinco acumulaciones de Arma vorágine o con Oleada de poder, y Nova de Fuego con cinco acumulaciones. Después, Choque de llamas siempre activo, Ráfaga de lava con Oleada de poder o mientras dure Choque de llamas, Golpe de tormenta, Choque de tierra, Descarga de relámpagos con cinco acumulaciones, Explosión de arrabio, Choque de Escarcha. Recordatorios: Muerdepiedras, Escudo de relámpagos, Espíritu del alfa sobre ti, Espíritu feral, Ira del chamán, Tótem abrasador o de magma, y tótems de grupo."
L["rm.tbc.shaman.elemental.icyveins.Name"] = "Elemental (Icy Veins y simulador)"
L["rm.tbc.shaman.elemental.icyveins.Description"] = "Elemental a distancia para el árbol de talentos Elemental. Descarga de relámpagos es el relleno; Cadena de relámpagos se lanza con Maestría elemental, con Lanzamiento libre mientras tengas un 40 % de maná, o libremente por encima del 80 %; Choque de llamas solo en movimiento; Choque de tierra interrumpe; Nova de Fuego, Cadena de relámpagos y magma contra grupos de enemigos. Antes de Cadena de relámpagos, a un objetivo cuerpo a cuerpo se le deja con el ataque automático para ahorrar maná. Recordatorios: Escudo de agua o de relámpagos, una imbuición de arma, Tótem de cólera (o Tótem abrasador en combates largos), Cólera de aire, Fuente de maná, Llamada totémica tras el combate, Maestría elemental y Ansia de sangre/Heroísmo."
L["rm.tbc.shaman.elemental.nextaction.Name"] = "Elemental (NextActionTBC)"
L["rm.tbc.shaman.elemental.nextaction.Description"] = "El Elemental de NextActionTBC, una alternativa a la rotación integrada de Elemental de Icy Veins recomendada, desactivada de forma predeterminada: actívala y desactiva aquella, o aumenta su prioridad. Mantiene Choque de llamas en el objetivo, Cadena de relámpagos solo contra dos o más enemigos mientras tengas más del 30 % de maná, y Descarga de relámpagos en los demás casos. Te recuerda Escudo de relámpagos, una imbuición de arma, Maestría elemental y Ansia de sangre/Heroísmo; los tótems siguen siendo manuales."
L["rm.tbc.shaman.elemental.wowhead.Name"] = "Elemental (Wowhead)"
L["rm.tbc.shaman.elemental.wowhead.Description"] = "El Elemental de Wowhead, una alternativa a la rotación integrada de Elemental de Icy Veins recomendada, desactivada de forma predeterminada: actívala y desactiva aquella, o aumenta su prioridad. A nivel 70, Cadena de relámpagos cada vez que esté disponible con Descargas de relámpagos entre medias (durante la subida de nivel, solo con Maestría elemental o Lanzamiento libre), Choque de llamas solo en movimiento y Choque de tierra para rematar a un objetivo que moriría antes de completar un lanzamiento. Los mismos recordatorios de tótems, escudos y tiempos de reutilización que la variante de Icy Veins."
L["rm.tbc.shaman.enhancement.icyveins.Name"] = "Mejora (Icy Veins)"
L["rm.tbc.shaman.enhancement.icyveins.Description"] = "Mejora cuerpo a cuerpo del nivel 1 al 70, y la opción predeterminada para cualquier chamán al que no se ajuste ninguna otra rotación integrada. Inicia el combate con Descarga de relámpagos a distancia, interrumpe con Choque de tierra, coloca los tótems Nova de Fuego y de magma con tres o más enemigos cerca, y después Golpe de tormenta, Choque de tierra mientras dure el perjuicio de Golpe de tormenta, Choque de llamas sobre un objetivo que vaya a sobrevivir, Choque de tierra cada vez que esté disponible y Descarga de relámpagos mientras el objetivo esté fuera de alcance. Recordatorios aparte: imbuiciones de arma, Escudo de agua o de relámpagos, Fuerza de la tierra, Viento Furioso (en grupo) o Gracia del aire (en solitario), Tótem abrasador en combates largos, tótems de agua, Ira del chamán, Ansia de sangre/Heroísmo contra jefes, y Garra de piedra y Elemental de Tierra en solitario. Elemental de Fuego es un paso opcional que empieza desactivado. La colocación de tótems, Lobo fantasmal y la sanación quedan a tu cargo."
L["rm.tbc.shaman.enhancement.simulator.Name"] = "Mejora (Wowhead y simulador)"
L["rm.tbc.shaman.enhancement.simulator.Description"] = "El modelo de banda de nivel 70 para alternar tótems, una alternativa a la rotación integrada de Mejora de Icy Veins recomendada, desactivada de forma predeterminada: actívala y desactiva aquella, o aumenta su prioridad. Golpe de tormenta, intercalar el Tótem Nova de Fuego, Choque de llamas siempre que haya desaparecido y Choque de tierra como choque principal, con Descarga de relámpagos solo fuera de alcance. Los recordatorios alternan los tótems Viento Furioso y Gracia del aire, mantienen colocado el Tótem abrasador, usan Ira del chamán cuando escasea el maná y comparten con la variante de Icy Veins el mantenimiento de imbuiciones, escudos y tótems."
L["rm.tbc.shaman.restoration.Name"] = "Restauración"
L["rm.tbc.shaman.restoration.Description"] = "Sanación para el árbol de talentos Restauración, sobre tu objetivo amistoso (o sobre ti si no tienes objetivo): Presteza de la Naturaleza y Ola de sanación u Ola de sanación inferior en emergencias, Curar envenenamiento y Curar enfermedad, Escudo de tierra sobre tu foco, Sanación en cadena cuando hay tres aliados heridos cerca y Ola de sanación en los demás casos. Con un objetivo hostil cambia a Choque de llamas y Descarga de relámpagos para jugar en solitario. Recordatorios: Escudo de agua, Escudo de tierra sobre tu foco (pon al tanque como foco), Marea de maná, Fuente de maná y Fuerza de la tierra en grupo, Ansia de sangre/Heroísmo. Elegir a quién sanar y con qué rango queda a tu cargo."
